import React, { useEffect, useMemo, useState } from 'react';
import ImageWithFallback from './ImageWithFallback';
import { resolveCaseImage } from '../utils/caseAssets';
import CaseVisual, { isArsenalCase } from './CaseVisual';
import { resolveItemImage } from '../utils/itemAssets';
import './CasePreviewModal.css';

const rarityRank = { 'Mil-Spec': 0, Restricted: 1, Classified: 2, Covert: 3, Contraband: 4, Extraordinary: 5, Legendary: 6, Mythic: 7 };

function colorFor(rarity) {
  const map = { 'Mil-Spec': '#60a5fa', Restricted: '#8b5cf6', Classified: '#d946ef', Covert: '#ef4444', Contraband: '#f59e0b', Extraordinary: '#facc15', Legendary: '#fb7185', Mythic: '#f0abfc' };
  return map[rarity] || '#94a3b8';
}

export default function CasePreviewModal({ caseData, onClose, onOpen, externalLoading=false }) {
  const details = caseData;
  const items = useMemo(() => [...(details?.items || [])].sort((a, b) => Number(b.probability || 0) - Number(a.probability || 0)), [details]);
  const raritySummary = useMemo(() => {
    const grouped = {};
    items.forEach((item) => { grouped[item.rarity] = (grouped[item.rarity] || 0) + Number(item.probability || 0); });
    return Object.entries(grouped).sort((a, b) => (rarityRank[a[0]] ?? 99) - (rarityRank[b[0]] ?? 99));
  }, [items]);
  if (!caseData) return null;
  const busy = Boolean(externalLoading);

  return (
    <div className="case-preview-backdrop" onClick={onClose}>
      <div className="case-preview-modal" onClick={(e) => e.stopPropagation()}>
        <button className="case-preview-close" onClick={onClose} aria-label="Fermer">×</button>
        <div className="case-preview-hero">
          <div className="case-preview-image-wrap">
            <div className="case-preview-glow" />
            {isArsenalCase(details?.name) ? <CaseVisual caseData={details} large /> : <ImageWithFallback src={resolveCaseImage(details)} alt={details.name} className="case-preview-image" />}
          </div>
          <div className="case-preview-head">
            <span className="case-preview-kicker">APERÇU DE LA CAISSE</span>
            <h2>{details.name}</h2>
            <p>{details.description || 'Découvre exactement ce que tu peux obtenir avant de lancer une ouverture.'}</p>
            <div className="case-preview-meta"><strong>{Number(details.price || 0).toLocaleString('fr-FR')} €</strong><span>{items.length} récompenses</span></div>
            <div className="case-preview-actions">
              <button className="case-preview-open" onClick={() => onOpen?.(details.id)}>OUVRIR LA CAISSE</button>
              <button className="case-preview-secondary" onClick={onClose}>FERMER</button>
            </div>
          </div>
        </div>

        <div className="case-preview-section-title"><span>CHANCES DE DROP PAR ARME</span><small>Les probabilités ci-dessous sont celles réellement tirées côté serveur.</small></div>
        <div className="case-preview-rarities">
          {raritySummary.map(([rarity, chance]) => (
            <div className="case-preview-rarity" key={rarity} style={{ '--rarity-color': colorFor(rarity) }}>
              <span className="case-preview-rarity-dot" />
              <strong>{rarity}</strong>
              <b>{chance.toFixed(2)}%</b>
            </div>
          ))}
        </div>
        <div className="case-preview-quality-note"><strong>QUALITÉ DU DROP</strong><span>Chaque skin reçoit aussi un état : mauvais, moyen, correct, bon ou comme neuf. L'état modifie sa valeur de revente.</span></div>

        <div className="case-preview-section-title"><span>CONTENU DÉTAILLÉ</span><small>Trié du plus probable au plus rare.</small></div>
        {busy ? <div className="case-preview-loading">Chargement des probabilités et des récompenses…</div> : (
          <div className="case-preview-items">
            {!items.length && <div className="case-preview-loading">Aucune récompense disponible pour cette caisse.</div>}
            {items.map((item) => {
              const chance = Number(item.probability || 0);
              const rarityColor = colorFor(item.rarity);
              return (
                <div className="case-preview-item" key={item.id}>
                  <div className="case-preview-item-image"><ImageWithFallback src={resolveItemImage(item)} alt={item.name} /></div>
                  <div className="case-preview-item-info">
                    <div className="case-preview-item-top"><strong>{item.name}</strong><span style={{ color: rarityColor }}>{item.rarity}</span></div>
                    <div className="case-preview-meter"><i style={{ width: `${Math.min(100, Math.max(0, chance))}%`, background: rarityColor }} /></div>
                    <div className="case-preview-item-bottom"><span>{chance.toFixed(2)} %</span><span>{Number(item.virtual_value || 0).toLocaleString('fr-FR')} €</span></div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}
